package com.techie345.moneys.financial.obligation;
import java.time.LocalDate; import java.util.UUID; import com.techie345.moneys.financial.FinancialEntity; import jakarta.persistence.*;
@Entity @Table(name="recurring_obligation") public class ObligationEntity extends FinancialEntity { @Column(nullable=false) String name; @Column(nullable=false) String category; @Column(name="amount_cents",nullable=false) long amountCents; @Column(nullable=false) String frequency; LocalDate nextDueDate; protected ObligationEntity(){} public ObligationEntity(UUID o,String n,String c,long a,String f,LocalDate d){ownerId=o;name=n;category=c;amountCents=a;frequency=f;nextDueDate=d;} public String getName(){return name;} public String getCategory(){return category;} public long getAmountCents(){return amountCents;} public String getFrequency(){return frequency;} public LocalDate getNextDueDate(){return nextDueDate;} public void update(String n,String c,long a,String f,LocalDate d){name=n;category=c;amountCents=a;frequency=f;nextDueDate=d;} }
